insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-2014', '["phrase"]'::jsonb, '{"advanced-native-2014-v1-audio":{"type":"mc","answers":["The checks were short but repeated, with time lost returning to the text."],"options":["The checks were short but repeated, with time lost returning to the text.","One uninterrupted check took the entire half-hour before reading began.","The alerts had been silenced, so the speaker read the full period without a break.","The speaker had deliberately scheduled a new task after each finished chapter."]},"advanced-native-2014-v2-reply":{"type":"mc","answers":["The effect depended on repetition, not only the length of a single check.","They were eating away at the time through repeated checks and restarts.","A short interruption happened often enough to break up the planned half-hour.","Returning to the text also took attention and time."],"options":["The effect depended on repetition, not only the length of a single check.","They were eating away at the time through repeated checks and restarts.","A short interruption happened often enough to break up the planned half-hour.","Returning to the text also took attention and time."]},"advanced-native-2014-v1-scene":{"type":"mc","answers":["This account does not yet show repeated interruptions eating away at the reading period; the message was handled before it began."],"options":["The description says the half-hour was stopped after each paragraph by another alert.","This account does not yet show repeated interruptions eating away at the reading period; the message was handled before it began.","The single reply establishes that she repeatedly returned to messages during the reading."]},"advanced-native-2014-v1-contrast":{"type":"mc","answers":["Every individual request must take a long time by itself."],"options":["The requests have a cumulative effect on available time.","Every individual request must take a long time by itself.","Their frequency may help explain the loss of time."]},"advanced-native-2014-v1-branch":{"type":"mc","answers":["Even short checks can eat away at the time when they keep making me restart; I would like a way to collect non-urgent questions."],"options":["Even short checks can eat away at the time when they keep making me restart; I would like a way to collect non-urgent questions.","I would judge the effect only by timing one reply, without counting how often I stop.","I would add up only the typing time and ignore the effort of finding my place in the text again."]},"advanced-native-2014-v1-final":{"type":"open","answers":["The repeated approval forms ate away at our preparation period, even though no single delay was long. Could we review which approvals were necessary and remove duplicate requests for the same information?","Our log suggests that repeated requests for the same details were eating away at preparation time rather than causing one large delay. Let us trace which checks actually served a purpose before simplifying the forms, so we retain the safeguards we still need."],"options":[]}}'::jsonb),
('advanced-native-2015', '["phrase"]'::jsonb, '{"advanced-native-2015-v1-audio":{"type":"mc","answers":["The speaker wanted one photograph but continued through a feed without a clear stopping point."],"options":["The speaker read a fixed twelve-photo album and stopped at its labelled final page.","The feed showed only the requested caption, with no other posts appearing.","The speaker closed the feed immediately after confirming the original caption.","The speaker wanted one photograph but continued through a feed without a clear stopping point."]},"advanced-native-2015-v2-reply":{"type":"mc","answers":["My attention moved from one exhibition photo to the following posts.","I continued browsing after losing sight of the original purpose.","I got caught in the endless scroll as more posts kept following.","The feed kept offering another item instead of a clear finish to the search."],"options":["My attention moved from one exhibition photo to the following posts.","I continued browsing after losing sight of the original purpose.","I got caught in the endless scroll as more posts kept following.","The feed kept offering another item instead of a clear finish to the search."]},"advanced-native-2015-v1-scene":{"type":"mc","answers":["A finite album with a clear ending is not by itself the endless scroll described by the feed image."],"options":["A finite album with a clear ending is not by itself the endless scroll described by the feed image.","Moving down the page establishes that more items kept appearing after the labelled ending.","The account says the person abandoned the twelve photographs to follow an unrelated feed."]},"advanced-native-2015-v1-contrast":{"type":"mc","answers":["The phrase proves that continuing through the feed was the speaker’s original plan."],"options":["The phrase proves that continuing through the feed was the speaker’s original plan.","More context can show what the speaker originally meant to do.","The speaker experienced a continuing feed without an obvious stopping point."]},"advanced-native-2015-v1-branch":{"type":"mc","answers":["The endless scroll concerns how content keeps continuing; a twelve-photo album with an end can involve the same finger movement."],"options":["I would classify the album only by whether a finger moves down the screen.","I would also call a long article the endless scroll on length alone, even if the text has a fixed conclusion.","The endless scroll concerns how content keeps continuing; a twelve-photo album with an end can involve the same finger movement."]},"advanced-native-2015-v1-final":{"type":"open","answers":["Let’s give the three stages a clear beginning and ending, rather than lose the process in the endless scroll. We can offer a separate archive link after the selected photographs and captions for visitors who want more.","I would keep the carpenter’s sequence separate from the endless scroll of other images. A finite set of captioned photographs can explain the process, with the full archive available by choice afterwards."],"options":[]}}'::jsonb),
('advanced-native-2016', '["phrase"]'::jsonb, '{"advanced-native-2016-v1-audio":{"type":"mc","answers":["The images were real but selective, leaving out other parts of the week."],"options":["The posts documented the repairs and disagreements in the same detail as the finished work.","The finished pieces were absent, and the feed concerned only problems before the workshop began.","The images were real but selective, leaving out other parts of the week.","The photographs had been established as staged copies from a different workshop."]},"advanced-native-2016-v2-reply":{"type":"mc","answers":["The late repairs and quiet disagreements were missing.","The photographs showed the finished work without the whole process behind it.","A real image could still represent only one part of the experience.","They were highlight reels, showing selected moments rather than everything that happened."],"options":["The late repairs and quiet disagreements were missing.","The photographs showed the finished work without the whole process behind it.","A real image could still represent only one part of the experience.","They were highlight reels, showing selected moments rather than everything that happened."]},"advanced-native-2016-v1-scene":{"type":"mc","answers":["Those pictures may be part of his highlight reel, but they do not establish what every other day was like."],"options":["The two pictures establish that he found every stage of the course equally easy.","Sharing a happy moment is itself a claim that the entire course contained no difficulty.","Those pictures may be part of his highlight reel, but they do not establish what every other day was like."]},"advanced-native-2016-v1-contrast":{"type":"mc","answers":["Treat the selective display as proof that every pictured achievement was fabricated."],"options":["Allow someone to celebrate without assuming the display is a complete life record.","Recognise that the selection may leave out ordinary or difficult moments.","Treat the selective display as proof that every pictured achievement was fabricated."]},"advanced-native-2016-v1-branch":{"type":"mc","answers":["Highlight reels can leave work out without inventing the finished piece; I would ask about the process rather than assume the image is false."],"options":["I would take the real finished image as enough to conclude that the whole workshop went smoothly.","Highlight reels can leave work out without inventing the finished piece; I would ask about the process rather than assume the image is false.","I thought posting only the finished piece meant the maker was claiming there had been no repairs."]},"advanced-native-2016-v1-final":{"type":"open","answers":["These photographs are part of my highlight reel, and I am genuinely happy to have finished the stool. The joints took another attempt; this is a moment I want to celebrate, not a record of everything else in my week.","Here is one piece of my highlight reel: a finished stool after reworking the joints. I am pleased with this part of the process, while keeping the rest of the week my own."],"options":[]}}'::jsonb),
('advanced-native-2017', '["phrase"]'::jsonb, '{"advanced-native-2017-v1-audio":{"type":"mc","answers":["They spent the session on poster choices instead of preparing the interview opening."],"options":["The guest had asked them to replace all interview questions with a poster.","They spent the session on poster choices instead of preparing the interview opening.","The poster comparison was the agreed purpose of the session, and the interview had already been completed.","They finished the interview questions before briefly checking a colour."]},"advanced-native-2017-v2-reply":{"type":"mc","answers":["It pulled us off track from preparing the questions we needed for the guest.","We ended with colours rather than an interview opening.","The activity did not serve the task we had agreed for that session.","We spent the available attention on something unrelated to the planned questions."],"options":["It pulled us off track from preparing the questions we needed for the guest.","We ended with colours rather than an interview opening.","The activity did not serve the task we had agreed for that session.","We spent the available attention on something unrelated to the planned questions."]},"advanced-native-2017-v1-scene":{"type":"mc","answers":["A relevant check does not necessarily pull her off track; it can support the argument she is working on."],"options":["A relevant check does not necessarily pull her off track; it can support the argument she is working on.","Checking the date shows she has chosen a new research question rather than refining the existing argument.","The date check concerned an unrelated event-planning task rather than the argument."]},"advanced-native-2017-v1-contrast":{"type":"mc","answers":["Assume the distracting topic has no value for any other purpose."],"options":["Identify the goal that attention has moved away from.","Assume the distracting topic has no value for any other purpose.","Explain why a different activity does or does not serve the current task."]},"advanced-native-2017-v1-branch":{"type":"mc","answers":["The poster work pulled us off track from the interview; I would return to the opening question before calling the preparation complete."],"options":["I would call the preparation finished because we completed the part that was easiest to agree on.","I would spend the remaining session refining the poster and leave question drafting until the guest arrives.","The poster work pulled us off track from the interview; I would return to the opening question before calling the preparation complete."]},"advanced-native-2017-v1-final":{"type":"open","answers":["Guessing about my family is pulling us off track from the viewpoint question I wanted help with. Could we stay with what the narrator says on the page, while leaving my private life out of this discussion?","I am happy to hear where the story is unclear, but speculation about my relatives pulls us off track. Please show me the passage that confused you so we can discuss how the viewpoint works."],"options":[]}}'::jsonb),
('advanced-native-2018', '["phrase"]'::jsonb, '{"advanced-native-2018-v1-audio":{"type":"mc","answers":["The speaker plans to stop after one update and use the agreed email route for a later question."],"options":["The speaker plans to stop after one update and use the agreed email route for a later question.","The speaker has promised to answer every group message before leaving tonight.","The group and account will be permanently deleted after the update.","The speaker will ignore the rehearsal update and send no question by any route."]},"advanced-native-2018-v2-reply":{"type":"mc","answers":["I intend to finish reading the update, then leave the app for now.","I will come off the app and use our agreed email exchange for tomorrow’s question.","I will stop using the app for the evening rather than try to clear every message.","The later question can wait for the communication route we have already agreed."],"options":["I intend to finish reading the update, then leave the app for now.","I will come off the app and use our agreed email exchange for tomorrow’s question.","I will stop using the app for the evening rather than try to clear every message.","The later question can wait for the communication route we have already agreed."]},"advanced-native-2018-v1-scene":{"type":"mc","answers":["Muting alerts does not by itself mean she has come off the app when she is still actively using it."],"options":["Muting alerts does not by itself mean she has come off the app when she is still actively using it.","Turning off the sound establishes that she has stopped reading and replying.","The account says she deleted the app before reading the group messages."]},"advanced-native-2018-v1-contrast":{"type":"mc","answers":["The speaker has necessarily deleted the account permanently."],"options":["The speaker has necessarily deleted the account permanently.","More context can specify when the pause ends.","The speaker plans to stop engaging with the app."]},"advanced-native-2018-v1-branch":{"type":"mc","answers":["I will come off the app tonight, but I still want your question through the email arrangement we agreed."],"options":["I thought tomorrow’s question had already been answered by tonight’s update, so I would not expect a separate email.","I will come off the app tonight, but I still want your question through the email arrangement we agreed.","I would treat leaving one app as cancelling our agreement to discuss the question by email."]},"advanced-native-2018-v1-final":{"type":"open","answers":["He said he had come off the platform for six weeks, not that he had stopped making work or receiving enquiries through his website. Could we keep those limits clear instead of describing a complete withdrawal?","Coming off social media in his account referred to that platform and that six-week period. Please retain the separate website contact rather than imply he ended every professional connection."],"options":[]}}'::jsonb),
('advanced-native-2020', '["phrase"]'::jsonb, '{"advanced-native-2020-v1-audio":{"type":"mc","answers":["Jin learned the basic controls easily but still needed guidance about permission to publish."],"options":["The tutor was teaching permission rules rather than demonstrating any recording controls.","Jin learned the basic controls easily but still needed guidance about permission to publish.","Jin had already obtained permission from the recorded speaker before learning the controls.","The account describes a long struggle with the basic controls followed by eventual success."]},"advanced-native-2020-v2-reply":{"type":"mc","answers":["Jin took to it like a duck to water when trying the basic controls.","The basic operation seemed easy from the first demonstration.","There was little difficulty starting the task, although permission was a separate question.","Jin quickly became comfortable using the controls that had just been shown."],"options":["Jin took to it like a duck to water when trying the basic controls.","The basic operation seemed easy from the first demonstration.","There was little difficulty starting the task, although permission was a separate question.","Jin quickly became comfortable using the controls that had just been shown."]},"advanced-native-2020-v1-scene":{"type":"mc","answers":["Her fluent performance does not establish that she took to it like a duck to water; her account describes a difficult beginning and later practice."],"options":["Her fluent performance does not establish that she took to it like a duck to water; her account describes a difficult beginning and later practice.","The final performance establishes that the first attempt felt equally easy.","The practice was needed only for performing in public, not for learning the difficult rhythm."]},"advanced-native-2020-v1-contrast":{"type":"mc","answers":["She had already mastered every advanced task connected with the activity."],"options":["She had already mastered every advanced task connected with the activity.","The context is needed to identify what it refers to.","She seemed to adapt easily to the activity in that context."]},"advanced-native-2020-v1-branch":{"type":"mc","answers":["Jin took to it like a duck to water, but that was the recorder; let us explain the permission process before assigning that responsibility."],"options":["I would assign the permission task now because confidence with the controls should be enough preparation.","I would make Jin repeat the basic controls lesson rather than explain the separate permission process.","Jin took to it like a duck to water, but that was the recorder; let us explain the permission process before assigning that responsibility."]},"advanced-native-2020-v1-final":{"type":"open","answers":["I took to it like a duck to water, but the others may need a slower demonstration of the fold. Could we show it once more and let them try again rather than finish their loaves for them?","I seem to have taken to it like a duck to water, but I do not want my pace to set the pace for everyone. Could we pause for one slow fold and give the other beginners another attempt?"],"options":[]}}'::jsonb),
('advanced-native-2021', '["phrase"]'::jsonb, '{"advanced-native-2021-v1-audio":{"type":"mc","answers":["The updates were present, but Lina’s attention was on her friend rather than their content."],"options":["The feed had been closed before the circle, so no updates were present.","The account establishes that the app’s announcements were factually incorrect.","The updates were present, but Lina’s attention was on her friend rather than their content.","Lina studied each new post and used it to question her friend’s account."]},"advanced-native-2021-v2-reply":{"type":"mc","answers":["She was following the spoken account rather than reading the feed.","An open feed did not mean its contents held her attention.","The posts were present, but she had not been attending to what they said.","The updates had become background noise while she concentrated on her friend’s story."],"options":["She was following the spoken account rather than reading the feed.","An open feed did not mean its contents held her attention.","The posts were present, but she had not been attending to what they said.","The updates had become background noise while she concentrated on her friend’s story."]},"advanced-native-2021-v1-scene":{"type":"mc","answers":["The date was spoken softly but actively noted, so low volume alone does not make it background noise in this figurative sense."],"options":["The listeners treated the date as a familiar detail they did not need to record.","The date was spoken softly but actively noted, so low volume alone does not make it background noise in this figurative sense.","Speaking softly establishes that the listeners ignored the date."]},"advanced-native-2021-v1-contrast":{"type":"mc","answers":["The updates had been checked and found unreliable."],"options":["She treated the updates as peripheral rather than her focus.","The updates had been checked and found unreliable.","Another person might attend to the same updates differently."]},"advanced-native-2021-v1-branch":{"type":"mc","answers":["They were background noise to her at that moment; that tells us where her attention was, not whether the announcements were true."],"options":["They were background noise to her at that moment; that tells us where her attention was, not whether the announcements were true.","I would use her inability to recall the posts as the reason to reject the announcements.","I would assume that leaving the feed open meant she had read the updates before listening to the story."]},"advanced-native-2021-v1-final":{"type":"open","answers":["The crowded board has become background noise, and students say they miss the deadline among the repeated posters. Could we remove the expired notices and keep one current notice with a clear due date?","Adding another large poster may leave the board as background noise rather than help students find the date. Please clear the old notices and give the current deadline its own uncluttered space."],"options":[]}}'::jsonb),
('advanced-native-2023', '["phrase"]'::jsonb, '{"advanced-native-2023-v1-audio":{"type":"mc","answers":["It applied fixed naming and formatting rules, while people evaluated the conflicting accounts."],"options":["It applied fixed naming and formatting rules, while people evaluated the conflicting accounts.","It resolved the conflicting accounts before any person compared them.","The people checked only file names, while the script chose the report’s interpretation.","The list contained the final factual conclusion rather than naming and formatting rules."]},"advanced-native-2023-v2-reply":{"type":"mc","answers":["The task it performed was applying established rules, not resolving the conflicting statements.","It handled the mechanical side of our work, following fixed names and formats rather than weighing the accounts.","The naming list told it what to apply, while we still had to compare the evidence.","Formatting completion did not decide which interpretation the report could support."],"options":["The task it performed was applying established rules, not resolving the conflicting statements.","It handled the mechanical side of our work, following fixed names and formats rather than weighing the accounts.","The naming list told it what to apply, while we still had to compare the evidence.","Formatting completion did not decide which interpretation the report could support."]},"advanced-native-2023-v1-scene":{"type":"mc","answers":["Using a computer does not make this the mechanical side of work; she is weighing evidence rather than merely applying a fixed format."],"options":["The description says she has left the evidence review to a script and is checking only file names.","Using a computer does not make this the mechanical side of work; she is weighing evidence rather than merely applying a fixed format.","The device establishes that she is following a predetermined interpretation without comparing accounts."]},"advanced-native-2023-v1-contrast":{"type":"mc","answers":["Treat every task performed on a computer as requiring no interpretation."],"options":["Recognise that routine execution can still require care and deserve credit.","Describe the repeatable steps that a fixed instruction list can specify.","Treat every task performed on a computer as requiring no interpretation."]},"advanced-native-2023-v1-branch":{"type":"mc","answers":["The mechanical side of our work is done, but we still need to compare those accounts before marking the claims as checked."],"options":["I would use consistent formatting as sufficient evidence that the different accounts agree.","I would finish the conclusion first and return to the contradictory details only if a reader challenges it.","The mechanical side of our work is done, but we still need to compare those accounts before marking the claims as checked."]},"advanced-native-2023-v1-final":{"type":"open","answers":["Mei took care of the mechanical side of our work, carefully applying the agreed numbers to each submission record. Her patient work made the files easy to find, while the editors remained responsible for checking the articles.","We thank Mei for the mechanical side of the work: numbering the submission records consistently so that we could locate each file. This careful contribution supported the yearbook without taking over the editors’ factual review."],"options":[]}}'::jsonb),
('advanced-native-2024', '["phrase"]'::jsonb, '{"advanced-native-2024-v1-audio":{"type":"mc","answers":["The tool suggested groupings, while Noor checked quotations and decided what to claim."],"options":["The project assigned quotation checking to the tool and grouping suggestions to Noor.","The tool suggested groupings, while Noor checked quotations and decided what to claim.","The tool’s proposed grouping was automatically the report’s final conclusion.","Noor’s only agreed job was to format a conclusion the tool had already approved."]},"advanced-native-2024-v2-reply":{"type":"mc","answers":["The tool was a co-pilot, and their arrangement left her responsible for checking the material behind the claims.","A proposed grouping did not establish that each quotation had been represented accurately.","She was the person assigned to choose what the report could claim.","The agreed support did not replace her review of the underlying words."],"options":["The tool was a co-pilot, and their arrangement left her responsible for checking the material behind the claims.","A proposed grouping did not establish that each quotation had been represented accurately.","She was the person assigned to choose what the report could claim.","The agreed support did not replace her review of the underlying words."]},"advanced-native-2024-v1-scene":{"type":"mc","answers":["Calling it a co-pilot does not establish the review he described; his actual process leaves the claims unchecked by him."],"options":["The supporting label establishes that he has already compared the quotations himself.","Any tool suggestion would prevent him from making a considered judgement of his own.","Calling it a co-pilot does not establish the review he described; his actual process leaves the claims unchecked by him."]},"advanced-native-2024-v1-contrast":{"type":"mc","answers":["The exact speaking, checking and decision duties have already been specified by the label alone."],"options":["She is using a partnership image to ask for support.","The exact speaking, checking and decision duties have already been specified by the label alone.","A discussion can clarify what support would actually help."]},"advanced-native-2024-v1-branch":{"type":"mc","answers":["It can be a co-pilot, but our agreement still puts quotation checks with us; let us review the passages before accepting the groupings."],"options":["I would accept the groups first and check the quotations only if the final headings look confusing.","I would reject the suggestions before reading them because accepting help would mean giving up our own judgement.","It can be a co-pilot, but our agreement still puts quotation checks with us; let us review the passages before accepting the groupings."]},"advanced-native-2024-v1-final":{"type":"open","answers":["I agreed to be a co-pilot for checking the labels, not for removing any pieces from the exhibition. Could you confirm who should make that decision if the organiser asks while I cannot reach you?","I am happy to remain your co-pilot on the numbers and captions, but choosing which work stays goes beyond our original agreement. Please name someone who can make that decision during your absence, or tell the organiser which requests should wait for you."],"options":[]}}'::jsonb),
('advanced-native-2026', '["phrase"]'::jsonb, '{"advanced-native-2026-v1-audio":{"type":"mc","answers":["The process and responsibilities had become unclear, but a closure had not been announced."],"options":["The workshop had announced permanent closure and cancelled the opening rota.","The old rota still fully explained the revised booking process.","The members had already agreed new opening responsibilities before the change.","The process and responsibilities had become unclear, but a closure had not been announced."]},"advanced-native-2026-v2-reply":{"type":"mc","answers":["We still needed to know who would take the new opening responsibilities.","The booking change affected how we could rely on the existing rota.","The ground was shifting under our feet because the old rota no longer clarified who would open the room.","A familiar arrangement no longer answered an important practical question."],"options":["We still needed to know who would take the new opening responsibilities.","The booking change affected how we could rely on the existing rota.","The ground was shifting under our feet because the old rota no longer clarified who would open the room.","A familiar arrangement no longer answered an important practical question."]},"advanced-native-2026-v1-scene":{"type":"mc","answers":["The ground is shifting under their feet as the familiar submission categories change, while the final rules remain unsettled."],"options":["The discussion establishes that the publication has already stopped accepting any work permanently.","The writers are following settled rules that have remained unchanged throughout.","The ground is shifting under their feet as the familiar submission categories change, while the final rules remain unsettled."]},"advanced-native-2026-v1-contrast":{"type":"mc","answers":["The final outcome has already been confirmed as the loss of their roles."],"options":["More detail is needed to identify which conditions are changing.","They experience a change as making familiar expectations less stable.","The final outcome has already been confirmed as the loss of their roles."]},"advanced-native-2026-v1-branch":{"type":"mc","answers":["The ground is shifting under our feet, but that is why we need to ask who opens under the new process rather than assume a closure."],"options":["I would keep using the old rota as the complete answer until a problem is reported at the door.","The ground is shifting under our feet, but that is why we need to ask who opens under the new process rather than assume a closure.","I would tell visitors not to come again until the old rota is restored, without asking about the new arrangements."]},"advanced-native-2026-v1-final":{"type":"open","answers":["I feel the ground is shifting under my feet now that the family is discussing a move, though no date or place for me has been decided. Before I imagine the whole term changing, I want to ask where I could stay until school finishes.","The ground is shifting under my feet: the home I expected for this term is suddenly a question rather than a settled arrangement. Tomorrow I will ask whether I can stay with Gran until the end of term, instead of treating the discussion as a completed move."],"options":[]}}'::jsonb),
('advanced-native-2027', '["phrase"]'::jsonb, '{"advanced-native-2027-v1-audio":{"type":"mc","answers":["The group could reach different visitors but still needed volunteers for another shift."],"options":["The group could reach different visitors but still needed volunteers for another shift.","The second shift was already fully staffed before the exhibition was proposed.","The evening opening removed the need for anyone to steward the exhibition.","The group had decided to stop showing work to visitors who could not attend during the day."]},"advanced-native-2027-v2-reply":{"type":"mc","answers":["The possible reach did not remove the work of covering the second shift.","It brought opportunity and pressure: access could widen, but another shift still needed people.","New visitors might attend, while the staffing arrangement was still incomplete.","The additional opening created a way to share the work and a new duty to organise."],"options":["The possible reach did not remove the work of covering the second shift.","It brought opportunity and pressure: access could widen, but another shift still needed people.","New visitors might attend, while the staffing arrangement was still incomplete.","The additional opening created a way to share the work and a new duty to organise."]},"advanced-native-2027-v1-scene":{"type":"mc","answers":["The change brings opportunity and pressure: a broader range of experiences and extra review work, with the volume still unknown."],"options":["The editors expect only a brief check of the outside submissions, rather than the additional review work described.","The description reports extra review work but no possible gain in the range of experiences.","The change brings opportunity and pressure: a broader range of experiences and extra review work, with the volume still unknown."]},"advanced-native-2027-v1-contrast":{"type":"mc","answers":["The benefits and burdens are exactly equal for every participant."],"options":["The benefits and burdens are exactly equal for every participant.","More context is needed to identify the particular possibility and demand.","The speaker sees both a possibility and a demand associated with the change."]},"advanced-native-2027-v1-branch":{"type":"mc","answers":["There is opportunity and pressure here; reaching new visitors still depends on arranging the extra shift properly."],"options":["I would confirm the opening first and ask the same volunteers to extend their hours only on the day.","I would reject the evening opening on staffing grounds before asking whether a shorter, fully covered session is possible.","There is opportunity and pressure here; reaching new visitors still depends on arranging the extra shift properly."]},"advanced-native-2027-v1-final":{"type":"open","answers":["There is opportunity and pressure in reading my own words at your wedding: I want to share something personal, and I am nervous about the moment. Could we try a short reading in the room beforehand so I can prepare without giving up the part I want to offer?","This reading brings opportunity and pressure, and I still want to do it myself. Could I visit the room for a brief practice, so the setting feels more familiar when I share the words I wrote for you?"],"options":[]}}'::jsonb),
